const fs = require('fs');
const path = require('path');
const ROOT = process.cwd();

const FILES = {"src/pages/OlympiadPage.jsx": "import React, { useState, useEffect, useRef, useCallback } from 'react';\nimport { useNavigate } from 'react-router-dom';\n// base44 removed\nimport { useLanguage } from '@/lib/LanguageContext';\nimport {\n  getOlympiadLevel,\n  getOlympiadLevelLabel,\n  getOlympiadStatus,\n  getNextOlympiadDate,\n  formatOlympiadDate,\n  getDaysUntil,\n  getQuarterId,\n  getCachedQuestions,\n  setCachedQuestions,\n  saveOlympiadResult,\n} from '@/lib/olympiadEngine';\n\n// ─── Helpers ─────────────────────────────────────────────────────────────────\n\nfunction getTodayStr() {\n  const { t } = useLanguage();\n  const now = new Date();\n  return (\n    now.getFullYear() +\n    '-' +\n    String(now.getMonth() + 1).padStart(2, '0') +\n    '-' +\n    String(now.getDate()).padStart(2, '0')\n  );\n}\n\nconst LEVEL_OPTIONS = [\n  { value: 'junior', label: 'Junior (Class 1–7)' },\n  { value: 'senior', label: 'Senior (Class 8–12)' },\n  { value: 'open', label: 'Open (Adults)' },\n];\n\nconst DARK_BG = { background: 'linear-gradient(135deg, #0A1628 0%, #0D2252 100%)', minHeight: '100vh' };\n\n// ─── Countdown Clock ─────────────────────────────────────────────────────────\n\nfunction useCountdown(targetHour) {\n  const [str, setStr] = useState('');\n  useEffect(() => {\n    function calc() {\n      const now = new Date();\n      const target = new Date();\n      target.setHours(targetHour, 0, 0, 0);\n      const diff = Math.max(0, target - now);\n      const h = String(Math.floor(diff / 3600000)).padStart(2, '0');\n      const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');\n      const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');\n      setStr(`${h}:${m}:${s}`);\n    }\n    calc();\n    const id = setInterval(calc, 1000);\n    return () => clearInterval(id);\n  }, [targetHour]);\n  return str;\n}\n\n// ─── Exam Timer ──────────────────────────────────────────────────────────────\n\nfunction useExamTimer(running) {\n  const [elapsed, setElapsed] = useState(0);\n  useEffect(() => {\n    if (!running) return;\n    const id = setInterval(() => setElapsed(e => e + 1), 1000);\n    return () => clearInterval(id);\n  }, [running]);\n  return elapsed;\n}\n\n// ─── Level Selector ──────────────────────────────────────────────────────────\n\nfunction LevelSelector({ level, onChange }) {\n  const [open, setOpen] = useState(false);\n  return (\n    <div style={{ position: 'relative', display: 'inline-block', marginBottom: 24 }}>\n      <button\n        onClick={() => setOpen(o => !o)}\n        style={{\n          background: '#F59E0B', color: '#0A1628',\n          border: 'none', borderRadius: 99, padding: '8px 18px',\n          fontFamily: 'var(--font-body)', fontSize: 13, fontWeight: 700,\n          cursor: 'pointer',\n        }}\n      >\n        {getOlympiadLevelLabel(level)} ✏️\n      </button>\n      {open && (\n        <div style={{\n          position: 'absolute', top: '110%', left: 0, zIndex: 10,\n          background: '#0D2252', border: '1px solid rgba(255,255,255,0.2)',\n          borderRadius: 12, overflow: 'hidden', minWidth: 200,\n        }}>\n          {LEVEL_OPTIONS.map(opt => (\n            <div\n              key={opt.value}\n              onClick={() => { onChange(opt.value); setOpen(false); }}\n              style={{\n                padding: '12px 16px', cursor: 'pointer',\n                fontFamily: 'var(--font-body)', fontSize: 14,\n                color: level === opt.value ? '#F59E0B' : 'white',\n                background: level === opt.value ? 'rgba(245,158,11,0.15)' : 'transparent',\n              }}\n            >\n              {opt.label}\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n\n// ─── Rules Modal ─────────────────────────────────────────────────────────────\n\nfunction RulesModal({ onStart }) {\n  return (\n    <div style={{\n      position: 'fixed', inset: 0, zIndex: 100,\n      background: 'rgba(0,0,0,0.85)',\n      display: 'flex', alignItems: 'center', justifyContent: 'center',\n      padding: 16,\n    }}>\n      <div style={{\n        background: '#0D2252', border: '1px solid rgba(245,158,11,0.4)',\n        borderRadius: 20, padding: 32, maxWidth: 400, width: '100%',\n        textAlign: 'center',\n      }}>\n        <div style={{ fontSize: 40, marginBottom: 12 }}>⚠️</div>\n        <div className=\"font-heading\" style={{ fontSize: 22, color: 'white', fontWeight: 700, marginBottom: 20 }}>\n          Olympiad Rules\n        </div>\n        {[\n          { icon: '✅', text: 'Correct answer: +5 points' },\n          { icon: '❌', text: 'Wrong answer: −1 point' },\n          { icon: '⬜', text: 'Unanswered: 0 points' },\n        ].map(r => (\n          <div key={r.text} style={{\n            display: 'flex', alignItems: 'center', gap: 10,\n            background: 'rgba(255,255,255,0.06)', borderRadius: 10,\n            padding: '10px 14px', marginBottom: 10, textAlign: 'left',\n          }}>\n            <span style={{ fontSize: 18 }}>{r.icon}</span>\n            <span style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: 'white' }}>{r.text}</span>\n          </div>\n        ))}\n        <p style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: 'rgba(255,255,255,0.6)', margin: '16px 0 20px' }}>\n          Think carefully before answering!\n        </p>\n        <button\n          onClick={onStart}\n          style={{\n            width: '100%', height: 48, background: '#F59E0B', color: '#0A1628',\n            border: 'none', borderRadius: 12, fontFamily: 'var(--font-body)',\n            fontSize: 15, fontWeight: 700, cursor: 'pointer',\n          }}\n        >\n          I Understand — Start Exam\n        </button>\n      </div>\n    </div>\n  );\n}\n\n// ─── Upcoming / Today Waiting State ──────────────────────────────────────────\n\nfunction UpcomingView({ level, onLevelChange, status }) {\n  const next = getNextOlympiadDate();\n  const days = getDaysUntil(next);\n  const countdown = useCountdown(10);\n  const progress = JSON.parse(localStorage.getItem('vedicmind_progress') || '{}');\n  const history = progress.olympiadHistory || [];\n  const lastResult = history.length > 0 ? history[history.length - 1] : null;\n\n  return (\n    <div style={{ ...DARK_BG, padding: '24px 16px', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>\n      <div style={{ maxWidth: 500, width: '100%', textAlign: 'center' }}>\n        <LevelSelector level={level} onChange={onLevelChange} />\n\n        <div style={{\n          fontSize: 56,\n          animation: status === 'today_waiting' ? 'olympiadPulse 1.5s ease-in-out infinite' : 'none',\n          marginBottom: 12,\n        }}>🏆</div>\n\n        <h1 className=\"font-heading\" style={{ fontSize: 32, fontWeight: 700, color: 'white', margin: '0 0 8px' }}>\n          VedicMind Olympiad\n        </h1>\n        <p style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: 'rgba(255,255,255,0.7)', margin: '0 0 24px' }}>\n          {getOlympiadLevelLabel(level)}\n        </p>\n\n        {/* Date card */}\n        <div style={{\n          background: 'rgba(255,255,255,0.08)',\n          border: '1px solid rgba(255,255,255,0.15)',\n          borderRadius: 16, padding: '20px 24px', marginBottom: 24,\n        }}>\n          <div style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: 'rgba(255,255,255,0.6)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 6 }}>\n            {status === 'today_waiting' ? '🌟 Olympiad Day!' : 'Next Olympiad'}\n          </div>\n          <div className=\"font-heading\" style={{ fontSize: 22, color: 'white', marginBottom: 8 }}>\n            {status === 'today_waiting' ? 'Begins at 10:00 AM sharp' : formatOlympiadDate(next)}\n          </div>\n          {status === 'today_waiting' ? (\n            <div style={{ fontFamily: 'var(--font-mono)', fontSize: 32, fontWeight: 700, color: '#F59E0B' }}>\n              Starts in {countdown}\n            </div>\n          ) : (\n            <div style={{ fontFamily: 'var(--font-mono)', fontSize: 32, fontWeight: 700, color: '#F59E0B' }}>\n              {days} day{days !== 1 ? 's' : ''} away\n            </div>\n          )}\n        </div>\n\n        {/* Info pills */}\n        <div style={{ display: 'flex', gap: 10, justifyContent: 'center', flexWrap: 'wrap', marginBottom: 24 }}>\n          {['📝 30 Questions', '⏱ 60 Minutes', '🏅 Win Certificates'].map(t => (\n            <span key={t} style={{\n              background: 'rgba(245,158,11,0.2)', border: '1px solid rgba(245,158,11,0.4)',\n              color: '#F59E0B', borderRadius: 99, padding: '8px 16px',\n              fontFamily: 'var(--font-body)', fontSize: 12,\n            }}>{t}</span>\n          ))}\n        </div>\n\n        {/* Prizes */}\n        <div style={{ textAlign: 'left', marginBottom: 24 }}>\n          <div style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: 'white', fontWeight: 600, marginBottom: 12 }}>\n            What You Can Win 🥇\n          </div>\n          {[\n            { icon: '🥇', text: '1st Place — Gold Certificate + Champion Badge + 500 XP' },\n            { icon: '🥈', text: '2nd Place — Silver Certificate + Elite Badge + 300 XP' },\n            { icon: '🥉', text: '3rd Place — Bronze Certificate + Achiever Badge + 200 XP' },\n            { icon: '🏅', text: 'All Participants — Participation Certificate + 50 XP' },\n          ].map(item => (\n            <div key={item.icon} style={{\n              display: 'flex', alignItems: 'flex-start', gap: 10,\n              background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)',\n              borderRadius: 12, padding: 12, marginBottom: 8,\n            }}>\n              <span style={{ fontSize: 18, flexShrink: 0 }}>{item.icon}</span>\n              <span style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: 'white' }}>{item.text}</span>\n            </div>\n          ))}\n        </div>\n\n        {/* Past result */}\n        {lastResult && (\n          <p style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: 'rgba(255,255,255,0.7)' }}>\n            Your last Olympiad: {lastResult.score}/{lastResult.totalPossible} — {lastResult.medal || '🏅 Participant'}\n          </p>\n        )}\n      </div>\n\n      <style>{`@keyframes olympiadPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}`}</style>\n    </div>\n  );\n}\n\n// ─── Exam Interface ───────────────────────────────────────────────────────────\n\nfunction ExamInterface({ level, questions }) {\n  const navigate = useNavigate();\n  const [showRules, setShowRules] = useState(true);\n  const [started, setStarted] = useState(false);\n  const [current, setCurrent] = useState(0);\n  const [answers, setAnswers] = useState({});\n  const [selected, setSelected] = useState(null);\n  const [showSubmitModal, setShowSubmitModal] = useState(false);\n  const [qElapsed, setQElapsed] = useState(0);\n  const elapsed = useExamTimer(started && !showSubmitModal);\n  const qTimerRef = useRef(null);\n\n  const TOTAL_TIME = 60 * 60;\n  const Q_TIME = 120;\n\n  // Per-question timer\n  useEffect(() => {\n    if (!started) return;\n    setQElapsed(0);\n    qTimerRef.current = setInterval(() => setQElapsed(e => e + 1), 1000);\n    return () => clearInterval(qTimerRef.current);\n  }, [current, started]);\n\n  // Auto-submit when time up\n  useEffect(() => {\n    if (started && elapsed >= TOTAL_TIME) submitExam();\n  }, [elapsed, started]);\n\n  const formatTime = (s) => {\n    const m = Math.floor(s / 60);\n    const sec = s % 60;\n    return `${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;\n  };\n\n  const timeLeft = Math.max(0, TOTAL_TIME - elapsed);\n  const qTimeLeft = Math.max(0, Q_TIME - qElapsed);\n  const timerColor = timeLeft < 300 ? '#EF4444' : '#F59E0B';\n\n  const handleSelect = (opt) => {\n    if (selected !== null || answers[current] !== undefined) return;\n    setSelected(opt);\n    clearInterval(qTimerRef.current);\n    const speedBonus = qElapsed < 20 ? 1 : 0;\n    setAnswers(prev => ({\n      ...prev,\n      [current]: { chosen: opt, speedBonus, timeSpent: qElapsed },\n    }));\n    setTimeout(() => {\n      if (current < questions.length - 1) {\n        setCurrent(c => c + 1);\n        setSelected(null);\n      } else {\n        setShowSubmitModal(true);\n      }\n    }, 700);\n  };\n\n  const submitExam = () => {\n    let correct = 0, wrong = 0, speedBonus = 0;\n    questions.forEach((q, i) => {\n      const ans = answers[i];\n      if (!ans) return;\n      if (ans.chosen === q.answer) { correct++; speedBonus += ans.speedBonus || 0; }\n      else wrong++;\n    });\n    const rawScore = correct * 5 - wrong * 1 + speedBonus;\n    const score = Math.max(0, rawScore);\n\n    const todayStr = getTodayStr();\n    let medal = null;\n    if (score >= 150) medal = '🥇 Gold';\n    else if (score >= 120) medal = '🥈 Silver';\n    else if (score >= 90) medal = '🥉 Bronze';\n\n    const result = {\n      date: todayStr,\n      quarter: getQuarterId(),\n      level,\n      score,\n      totalPossible: 180,\n      correct,\n      wrong,\n      timeTaken: elapsed,\n      completedAt: new Date().toISOString(),\n      rank: null,\n      medal,\n    };\n    saveOlympiadResult(result);\n    navigate('/olympiad/results');\n  };\n\n  const q = questions[current];\n  const answered = answers[current];\n  const qPct = ((current) / questions.length) * 100;\n  const qTimePct = (qTimeLeft / Q_TIME) * 100;\n  const qTimerColor = qTimeLeft < 30 ? '#EF4444' : '#F59E0B';\n\n  return (\n    <>\n      {showRules && <RulesModal onStart={() => { setShowRules(false); setStarted(true); }} />}\n\n      <div style={{ ...DARK_BG, display: 'flex', flexDirection: 'column' }}>\n        {/* Sticky Header */}\n        <div style={{\n          position: 'sticky', top: 0, zIndex: 50,\n          background: 'rgba(10,22,40,0.97)', backdropFilter: 'blur(12px)',\n          borderBottom: '1px solid rgba(245,158,11,0.2)',\n          padding: '12px 16px',\n        }}>\n          <div style={{ maxWidth: 700, margin: '0 auto', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>\n            <div style={{ fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 14, color: '#F59E0B', whiteSpace: 'nowrap' }}>\n              🏅 VedicMind Olympiad\n            </div>\n            <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: 'rgba(255,255,255,0.8)' }}>\n              Q{current + 1} of {questions.length}\n            </div>\n            <div style={{\n              fontFamily: 'var(--font-mono)', fontSize: 16, fontWeight: 700,\n              color: timerColor, background: 'rgba(255,255,255,0.08)',\n              borderRadius: 8, padding: '4px 10px',\n            }}>\n              {formatTime(timeLeft)}\n            </div>\n          </div>\n          {/* Progress bar */}\n          <div style={{ maxWidth: 700, margin: '8px auto 0', height: 4, background: 'rgba(255,255,255,0.1)', borderRadius: 99 }}>\n            <div style={{ height: '100%', width: `${qPct}%`, background: '#F59E0B', borderRadius: 99, transition: 'width 0.3s' }} />\n          </div>\n          {/* Dot nav */}\n          <div style={{ maxWidth: 700, margin: '8px auto 0', display: 'flex', gap: 3, flexWrap: 'wrap' }}>\n            {questions.map((_, i) => {\n              const a = answers[i];\n              const isCorrect = a && a.chosen === questions[i].answer;\n              const bg = i === current ? '#F59E0B' : a ? (isCorrect ? '#10B981' : '#EF4444') : 'rgba(255,255,255,0.2)';\n              return <div key={i} style={{ width: 10, height: 10, borderRadius: '50%', background: bg, flexShrink: 0 }} />;\n            })}\n          </div>\n        </div>\n\n        {/* Question */}\n        <div style={{ flex: 1, padding: '24px 16px', display: 'flex', justifyContent: 'center' }}>\n          <div style={{ maxWidth: 700, width: '100%' }}>\n            {/* Q badge + per-question timer */}\n            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>\n              <span style={{\n                background: '#F59E0B', color: '#0A1628',\n                borderRadius: 8, padding: '4px 12px',\n                fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 13,\n              }}>\n                Q{current + 1}\n              </span>\n              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>\n                <div style={{ width: 80, height: 6, background: 'rgba(255,255,255,0.1)', borderRadius: 99 }}>\n                  <div style={{ height: '100%', width: `${qTimePct}%`, background: qTimerColor, borderRadius: 99, transition: 'width 1s linear' }} />\n                </div>\n                <span style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: qTimerColor }}>{qTimeLeft}s</span>\n              </div>\n            </div>\n\n            {/* Question text */}\n            <div style={{\n              background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(245,158,11,0.2)',\n              borderRadius: 16, padding: '20px 20px 24px',\n            }}>\n              {q.sutra && (\n                <div style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: '#F59E0B', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 10 }}>\n                  {q.topic} · {q.sutra}\n                </div>\n              )}\n              <p style={{ fontFamily: 'var(--font-body)', fontSize: 17, color: 'white', fontWeight: 500, lineHeight: 1.6, margin: 0 }}>\n                {q.question}\n              </p>\n            </div>\n\n            {/* Options */}\n            <div style={{ marginTop: 16, display: 'flex', flexDirection: 'column', gap: 10 }}>\n              {(q.options || []).map((opt, i) => {\n                const isChosen = answered?.chosen === opt;\n                const isCorrect = q.answer === opt;\n                let border = '1px solid rgba(255,255,255,0.12)';\n                let bg = 'rgba(255,255,255,0.04)';\n                let color = 'rgba(255,255,255,0.9)';\n                if (answered) {\n                  if (isChosen && isCorrect) { border = '2px solid #10B981'; bg = 'rgba(16,185,129,0.15)'; color = '#10B981'; }\n                  else if (isChosen && !isCorrect) { border = '2px solid #EF4444'; bg = 'rgba(239,68,68,0.15)'; color = '#EF4444'; }\n                  else if (isCorrect) { border = '2px solid #10B981'; bg = 'rgba(16,185,129,0.1)'; }\n                } else if (selected === opt) {\n                  border = '2px solid #F59E0B'; bg = 'rgba(245,158,11,0.15)'; color = '#F59E0B';\n                }\n                return (\n                  <button\n                    key={i}\n                    onClick={() => handleSelect(opt)}\n                    disabled={!!answered}\n                    style={{\n                      width: '100%', minHeight: 48, textAlign: 'left',\n                      background: bg, border, borderRadius: 12,\n                      padding: '12px 16px', cursor: answered ? 'default' : 'pointer',\n                      fontFamily: 'var(--font-body)', fontSize: 14, color,\n                      transition: 'all 0.2s',\n                    }}\n                  >\n                    <span style={{\n                      display: 'inline-flex', alignItems: 'center', justifyContent: 'center',\n                      width: 24, height: 24, background: 'rgba(255,255,255,0.1)',\n                      borderRadius: '50%', fontSize: 12, fontWeight: 700, marginRight: 10, flexShrink: 0,\n                    }}>\n                      {String.fromCharCode(65 + i)}\n                    </span>\n                    {opt}\n                  </button>\n                );\n              })}\n            </div>\n\n            {/* Hint */}\n            {answered && q.hint && (\n              <div style={{\n                marginTop: 12, background: 'rgba(245,158,11,0.1)',\n                border: '1px solid rgba(245,158,11,0.3)', borderRadius: 10, padding: 12,\n              }}>\n                <span style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#F59E0B' }}>💡 {q.hint}</span>\n              </div>\n            )}\n\n            {/* Nav buttons */}\n            <div style={{ display: 'flex', gap: 12, marginTop: 20 }}>\n              {current > 0 && (\n                <button\n                  onClick={() => { setCurrent(c => c - 1); setSelected(answers[current - 1]?.chosen || null); }}\n                  style={{\n                    flex: 1, height: 44, background: 'rgba(255,255,255,0.08)',\n                    border: '1px solid rgba(255,255,255,0.15)', borderRadius: 10,\n                    color: 'white', fontFamily: 'var(--font-body)', fontSize: 14, cursor: 'pointer',\n                  }}\n                >\n                  ← Previous\n                </button>\n              )}\n              {current < questions.length - 1 ? (\n                <button\n                  onClick={() => { setCurrent(c => c + 1); setSelected(answers[current + 1]?.chosen || null); }}\n                  style={{\n                    flex: 1, height: 44, background: '#F59E0B', color: '#0A1628',\n                    border: 'none', borderRadius: 10,\n                    fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 14, cursor: 'pointer',\n                  }}\n                >\n                  Next →\n                </button>\n              ) : (\n                <button\n                  onClick={() => setShowSubmitModal(true)}\n                  style={{\n                    flex: 1, height: 44, background: '#10B981', color: 'white',\n                    border: 'none', borderRadius: 10,\n                    fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 14, cursor: 'pointer',\n                  }}\n                >\n                  Submit Exam ✓\n                </button>\n              )}\n            </div>\n          </div>\n        </div>\n      </div>\n\n      {/* Submit confirmation modal */}\n      {showSubmitModal && (\n        <div style={{\n          position: 'fixed', inset: 0, zIndex: 200,\n          background: 'rgba(0,0,0,0.85)',\n          display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16,\n        }}>\n          <div style={{\n            background: '#0D2252', border: '1px solid rgba(245,158,11,0.4)',\n            borderRadius: 20, padding: 28, maxWidth: 360, width: '100%', textAlign: 'center',\n          }}>\n            <div style={{ fontSize: 36, marginBottom: 12 }}>🏅</div>\n            <div className=\"font-heading\" style={{ fontSize: 20, color: 'white', fontWeight: 700, marginBottom: 8 }}>\n              Submit Olympiad?\n            </div>\n            <p style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: 'rgba(255,255,255,0.6)', marginBottom: 20 }}>\n              Answered: {Object.keys(answers).length} / {questions.length} · Time left: {formatTime(timeLeft)}\n            </p>\n            <div style={{ display: 'flex', gap: 10 }}>\n              <button\n                onClick={() => setShowSubmitModal(false)}\n                style={{\n                  flex: 1, height: 44, background: 'transparent',\n                  border: '1px solid rgba(255,255,255,0.3)', borderRadius: 10,\n                  color: 'white', fontFamily: 'var(--font-body)', fontSize: 14, cursor: 'pointer',\n                }}\n              >\n                Continue\n              </button>\n              <button\n                onClick={submitExam}\n                style={{\n                  flex: 1, height: 44, background: '#F59E0B', color: '#0A1628',\n                  border: 'none', borderRadius: 10,\n                  fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 14, cursor: 'pointer',\n                }}\n              >\n                Submit\n              </button>\n            </div>\n          </div>\n        </div>\n      )}\n    </>\n  );\n}\n\n// ─── Completed View ───────────────────────────────────────────────────────────\n\nfunction CompletedView() {\n  const navigate = useNavigate();\n  const progress = JSON.parse(localStorage.getItem('vedicmind_progress') || '{}');\n  const history = progress.olympiadHistory || [];\n  const last = history[history.length - 1];\n\n  return (\n    <div style={{ ...DARK_BG, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}>\n      <div style={{ maxWidth: 400, width: '100%', textAlign: 'center' }}>\n        <div style={{ fontSize: 56, marginBottom: 16 }}>🏅</div>\n        <h1 className=\"font-heading\" style={{ fontSize: 28, color: 'white', fontWeight: 700, marginBottom: 8 }}>\n          You've Competed!\n        </h1>\n        <p style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: 'rgba(255,255,255,0.7)', marginBottom: 24 }}>\n          {last ? `Score: ${last.score}/${last.totalPossible} · ${last.medal || '🏅 Participant'}` : 'Great effort this quarter!'}\n        </p>\n        <button\n          onClick={() => navigate('/olympiad/results')}\n          style={{\n            width: '100%', height: 48, background: '#F59E0B', color: '#0A1628',\n            border: 'none', borderRadius: 12, fontFamily: 'var(--font-body)',\n            fontWeight: 700, fontSize: 15, cursor: 'pointer', marginBottom: 12,\n          }}\n        >\n          View Results →\n        </button>\n        <button\n          onClick={() => navigate('/dashboard')}\n          style={{\n            width: '100%', height: 44, background: 'transparent',\n            border: '1px solid rgba(255,255,255,0.3)', borderRadius: 12,\n            color: 'white', fontFamily: 'var(--font-body)', fontSize: 14, cursor: 'pointer',\n          }}\n        >\n          {t('backToDashboard')}\n        </button>\n      </div>\n    </div>\n  );\n}\n\n// ─── Question Loader ─────────────────────────────────────────────────────────\n\nconst PROMPTS = {\n  junior: `Generate 30 Vedic Mathematics Olympiad MCQ questions for Class 1-7 students. Mix of difficulty: 12 easy, 12 medium, 6 hard. Topics: all Level 1-2 sutras. Include visual/pattern questions where possible. Each: question, options (array of 4 strings), answer (exact string matching one option), hint, difficulty, topic, sutra. Return a JSON array only, no markdown.`,\n  senior: `Generate 30 Vedic Mathematics Olympiad MCQ questions for Class 8-12 students. Mix: 8 medium, 14 hard, 8 very hard. Topics: all Level 1-3 sutras, algebraic applications, divisibility. Each: question, options (array of 4 strings), answer (exact string matching one option), hint, difficulty, topic, sutra. Return a JSON array only, no markdown.`,\n  open: `Generate 30 Vedic Mathematics Olympiad MCQ questions for adults and competitive exam aspirants. All hard to very hard. Topics: all 16 sutras, calendar, auxiliary fractions, osculators, speed arithmetic, mental calculation tricks. Timed pressure questions. Each: question, options (array of 4 strings), answer (exact string matching one option), hint, difficulty, topic, sutra. Return a JSON array only, no markdown.`,\n};\n\nfunction LoadingScreen({ level }) {\n  return (\n    <div style={{ ...DARK_BG, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}>\n      <div style={{ textAlign: 'center' }}>\n        <div style={{ fontSize: 48, marginBottom: 16 }}>⚡</div>\n        <div className=\"font-heading\" style={{ fontSize: 24, color: 'white', fontWeight: 700, marginBottom: 8 }}>\n          Preparing Your Olympiad\n        </div>\n        <p style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: 'rgba(255,255,255,0.6)', marginBottom: 24 }}>\n          Generating {getOlympiadLevelLabel(level)} questions...\n        </p>\n        <div style={{ display: 'flex', gap: 8, justifyContent: 'center' }}>\n          {[0, 1, 2].map(i => (\n            <div key={i} style={{\n              width: 10, height: 10, borderRadius: '50%', background: '#F59E0B',\n              animation: `loadDot 1.2s ease-in-out ${i * 0.2}s infinite`,\n            }} />\n          ))}\n        </div>\n        <style>{`@keyframes loadDot{0%,100%{opacity:0.3;transform:scale(0.8)}50%{opacity:1;transform:scale(1.2)}}`}</style>\n      </div>\n    </div>\n  );\n}\n\n// ─── Main Page ────────────────────────────────────────────────────────────────\n\nexport default function OlympiadPage() {\n  const profile = (() => { try { return JSON.parse(localStorage.getItem('vedicmind_profile') || '{}'); } catch { return {}; } })();\n  const [level, setLevel] = useState(() => getOlympiadLevel(profile.grade));\n  const [status, setStatus] = useState(getOlympiadStatus());\n  const [questions, setQuestions] = useState(null);\n  const [loadingQ, setLoadingQ] = useState(false);\n  const [loadError, setLoadError] = useState(null);\n\n  // Refresh status every 30s\n  useEffect(() => {\n    const id = setInterval(() => setStatus(getOlympiadStatus()), 30000);\n    return () => clearInterval(id);\n  }, []);\n\n  // Load questions when live\n  useEffect(() => {\n    if (status !== 'live') return;\n    const cached = getCachedQuestions(level);\n    if (cached) { setQuestions(cached); return; }\n    setLoadingQ(true);\n    setLoadError(null);\n    base44.integrations.Core.InvokeLLM({\n      prompt: PROMPTS[level],\n      response_json_schema: {\n        type: 'object',\n        properties: {\n          questions: {\n            type: 'array',\n            items: {\n              type: 'object',\n              properties: {\n                question: { type: 'string' },\n                options: { type: 'array', items: { type: 'string' } },\n                answer: { type: 'string' },\n                hint: { type: 'string' },\n                difficulty: { type: 'string' },\n                topic: { type: 'string' },\n                sutra: { type: 'string' },\n              },\n            },\n          },\n        },\n      },\n    })\n      .then(res => {\n        const qs = res.questions || res;\n        const arr = Array.isArray(qs) ? qs : [];\n        setCachedQuestions(level, arr);\n        setQuestions(arr);\n        setLoadingQ(false);\n      })\n      .catch(err => {\n        setLoadError(err.message || 'Failed to load questions');\n        setLoadingQ(false);\n      });\n  }, [status, level]);\n\n  if (status === 'live') {\n    if (loadingQ) return <LoadingScreen level={level} />;\n    if (loadError) return (\n      <div style={{ ...DARK_BG, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}>\n        <div style={{ textAlign: 'center' }}>\n          <div style={{ fontSize: 36, marginBottom: 12 }}>⚠️</div>\n          <p style={{ color: 'white', fontFamily: 'var(--font-body)', marginBottom: 16 }}>{loadError}</p>\n          <button onClick={() => window.location.reload()} style={{ padding: '10px 24px', background: '#F59E0B', color: '#0A1628', border: 'none', borderRadius: 10, cursor: 'pointer', fontFamily: 'var(--font-body)', fontWeight: 700 }}>Retry</button>\n        </div>\n      </div>\n    );\n    if (questions) return <ExamInterface level={level} questions={questions} />;\n    return null;\n  }\n\n  if (status === 'completed') return <CompletedView />;\n\n  return <UpcomingView level={level} onLevelChange={setLevel} status={status} />;\n}", "src/pages/LeaderboardPage.jsx": "import React, { useState, useMemo } from 'react';\nimport { useNavigate } from 'react-router-dom';\nimport { useVedicAuth } from '@/lib/VedicAuthContext';\nimport { motion } from 'framer-motion';\nimport usePullToRefresh from '@/hooks/usePullToRefresh';\nimport DashboardNavbar from '@/components/dashboard/DashboardNavbar';\nimport { useLanguage } from '@/lib/LanguageContext';\nimport {\n  generateLeaderboard, getUserEntry, getTopN,\n  getUserPercentile, filterByPeriod,\n} from '@/lib/leaderboardEngine';\n\nconst glass = {\n  background: 'rgba(255,255,255,0.75)',\n  backdropFilter: 'blur(20px)',\n  WebkitBackdropFilter: 'blur(20px)',\n  border: '1px solid rgba(30,64,175,0.15)',\n  boxShadow: '0 8px 32px rgba(10,22,40,0.08)',\n  borderRadius: 16,\n};\n\nconst avatarColors = { 0: '#FEF3C7', 1: '#F3F4F6', 2: '#FEF9EE' };\nconst scoreColors  = { 0: '#F59E0B', 1: '#6B7280', 2: '#D97706' };\nconst baseHeights  = { 0: 100, 1: 70, 2: 50 };\nconst medals = ['🥇', '🥈', '🥉'];\n\nfunction Toggle({\n  const { t } = useLanguage(); value, onChange }) {\n  return (\n    <div\n      onClick={() => onChange(!value)}\n      style={{\n        width: 44, height: 24, borderRadius: 100, cursor: 'pointer',\n        background: value ? '#10B981' : '#D1D5DB',\n        position: 'relative', transition: 'background 0.2s', flexShrink: 0,\n      }}\n    >\n      <div style={{\n        position: 'absolute', top: 2, left: value ? 22 : 2,\n        width: 20, height: 20, borderRadius: '50%', background: 'white',\n        transition: 'left 0.2s', boxShadow: '0 1px 4px rgba(0,0,0,0.2)',\n      }} />\n    </div>\n  );\n}\n\nexport default function LeaderboardPage() {\n  const navigate = useNavigate();\n  const { user, loading } = useVedicAuth();\n\nconst auth     = (() => { try { return JSON.parse(localStorage.getItem('vedicmind_auth')) || JSON.parse(localStorage.getItem('vedicmind-auth'))?.user || null; } catch { return null; } })();  const profile  = (() => { try { return JSON.parse(localStorage.getItem('vedicmind_profile')) || {}; } catch { return {}; } })();\n  const [progress, setProgress] = useState(() => { try { return JSON.parse(localStorage.getItem('vedicmind_progress')) || {}; } catch { return {}; } });\n\n  React.useEffect(() => {\n    if (!loading && !user) { navigate('/auth'); return; }\n  }, []);\n\n  const classBoard  = useMemo(() => generateLeaderboard(profile, progress, 'class'),  []);\n  const schoolBoard = useMemo(() => generateLeaderboard(profile, progress, 'school'), []);\n  const globalBoard = useMemo(() => generateLeaderboard(profile, progress, 'global'), []);\n\n  const [activeTab, setActiveTab]       = useState('vedic'); // vedic | aptitude\n  const [activeScope, setActiveScope]   = useState('class');\n  const [activePeriod, setActivePeriod] = useState('alltime');\n  const [visibleCount, setVisibleCount] = useState(20);\n\n  const base = activeScope === 'class' ? classBoard : activeScope === 'school' ? schoolBoard : globalBoard;\n  const activeBoard = useMemo(() => filterByPeriod(base, activePeriod), [base, activePeriod]);\n\n  const userEntry   = getUserEntry(activeBoard);\n  const top3        = getTopN(activeBoard, 3);\n  const percentile  = getUserPercentile(activeBoard);\n  const tableRows   = activeBoard.slice(3, visibleCount + 3);\n  const remaining   = activeBoard.length - 3 - visibleCount;\n  const userVisible = userEntry && (userEntry.rank <= 3 || (userEntry.rank - 3) <= visibleCount);\n\n  const { pulling, pullDistance } = usePullToRefresh(() => window.location.reload());\n\n  const handleOptOut = (val) => {\n    const updated = { ...progress, leaderboardOptOut: !val };\n    setProgress(updated);\n    localStorage.setItem('vedicmind_progress', JSON.stringify(updated));\n    window.location.reload(); // re-generate leaderboard with new opt-out state\n  };\n\n  const SCOPES = [\n    { id: 'class',  label: `📚 Class · ${classBoard.length} students` },\n    { id: 'school', label: `🏫 School · ${schoolBoard.length} students` },\n    { id: 'global', label: `🌍 Global · ${globalBoard.length} students` },\n  ];\n  const PERIODS = [\n    { id: 'daily',   label: 'Daily' },\n    { id: 'weekly',  label: 'Weekly' },\n    { id: 'monthly', label: 'Monthly' },\n    { id: 'alltime', label: 'All Time' },\n  ];\n\n  const podiumOrder = [1, 0, 2]; // silver, gold, bronze\n\n  return (\n    <div style={{ minHeight: '100vh', background: '#F0F4FF' }}>\n      <DashboardNavbar />\n      <style>{`\n        @media(max-width:640px){\n          .lb-header-row{flex-direction:column!important;gap:16px!important;}\n          .lb-rank-card{width:100%!important;text-align:left!important;display:flex!important;align-items:center!important;gap:24px!important;}\n          .lb-scope-scroll{overflow-x:auto!important;-webkit-overflow-scrolling:touch!important;}\n          .lb-scope-scroll::-webkit-scrollbar{display:none!important;}\n          .lb-podium-card{padding:8px!important;}\n          .lb-podium-avatar{width:40px!important;height:40px!important;font-size:14px!important;}\n          .lb-hide-mobile{display:none!important;}\n          .lb-stats-grid{grid-template-columns:1fr!important;}\n          .lb-table-cols{grid-template-columns:40px 1fr 80px 60px!important;}\n        }\n        @media(min-width:641px){\n          .lb-table-cols{grid-template-columns:40px 1fr 80px 90px 60px 60px;}\n        }\n      `}</style>\n\n      {pulling && (\n        <div style={{ textAlign: 'center', padding: '8px 0', fontSize: 13, color: '#3B82F6', fontFamily: 'var(--font-body)', transform: `translateY(${pullDistance * 0.4}px)`, transition: 'transform 0.1s' }}>\n          {pullDistance >= 80 ? '↑ Release to refresh' : '↓ Pull to refresh'}\n        </div>\n      )}\n      <main style={{ maxWidth: 900, margin: '0 auto', padding: '24px 16px 60px' }}>\n        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>\n\n          {/* ── MODE TABS ── */}\n          <div style={{ display: 'flex', gap: 4, background: 'white', borderRadius: 14, padding: 4, border: '1px solid rgba(30,64,175,0.12)', marginBottom: 24, width: 'fit-content' }}>\n            {[{ id: 'vedic', label: '🧮 Vedic Maths' }, { id: 'aptitude', label: '🎯 Aptitude Zone' }].map(t => (\n              <button key={t.id} onClick={() => setActiveTab(t.id)} style={{\n                padding: '8px 20px', minHeight: 40, borderRadius: 10, border: 'none', cursor: 'pointer',\n                fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 14,\n                background: activeTab === t.id ? '#0A1628' : 'transparent',\n                color: activeTab === t.id ? 'white' : '#4B5563', transition: 'all 0.15s',\n              }}>{t.label}</button>\n            ))}\n          </div>\n\n          {/* ── PAGE HEADER ── */}\n          <div className=\"lb-header-row\" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>\n            <div>\n              <h1 className=\"font-heading\" style={{ fontSize: 32, fontWeight: 700, color: '#0A1628', marginBottom: 6 }}>🏆 Leaderboard</h1>\n              <p style={{ fontFamily: 'var(--font-body)', fontSize: 15, color: '#4B5563', margin: '0 0 8px' }}>See how you rank against other students</p>\n              <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>\n                <span style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#4B5563' }}>🔒 Names shown as First + Last Initial only</span>\n                <button onClick={() => navigate('/profile')} style={{ background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-body)', fontSize: 12, color: '#3B82F6', padding: 0 }}>\n                  Change privacy settings →\n                </button>\n              </div>\n            </div>\n            {userEntry && (\n              <div className=\"lb-rank-card\" style={{ ...glass, padding: '12px 20px', textAlign: 'center', minWidth: 140 }}>\n                <div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: '#4B5563', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 2 }}>{t('yourRank')}</div>\n                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: 36, fontWeight: 700, color: '#0A1628', lineHeight: 1 }}>#{userEntry.rank}</div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: '#4B5563', marginTop: 2 }}>of {activeBoard.length} students</div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#10B981', marginTop: 4 }}>↑{userEntry.movementAmount}</div>\n                </div>\n              </div>\n            )}\n          </div>\n\n          {/* ── APTITUDE TAB CONTENT ── */}\n          {activeTab === 'aptitude' && (() => {\n            const history = progress.aptitudeHistory || [];\n            const classGroup = profile.aptitudeClass ? (() => {\n              const n = parseInt(profile.aptitudeClass);\n              if (n <= 5) return 'Primary (1–5)';\n              if (n <= 8) return 'Middle (6–8)';\n              if (n <= 10) return 'Secondary (9–10)';\n              return 'Intermediate (11–12)';\n            })() : null;\n            const bestScore = progress.aptitudeScore || 0;\n            const totalAttempts = history.length;\n            const allSutras = [...new Set(history.flatMap(h => h.sutras || []))];\n            return (\n              <div>\n                {totalAttempts === 0 ? (\n                  <div style={{ ...glass, padding: 40, textAlign: 'center' }}>\n                    <div style={{ fontSize: 48, marginBottom: 16 }}>🎯</div>\n                    <h3 className=\"font-heading\" style={{ fontSize: 22, fontWeight: 700, color: '#0A1628', marginBottom: 8 }}>No Aptitude Attempts Yet</h3>\n                    <p style={{ fontFamily: 'var(--font-body)', fontSize: 15, color: '#4B5563', marginBottom: 20 }}>\n                      Complete some Aptitude Zone quizzes to see your stats here.\n                    </p>\n                    <button onClick={() => navigate('/aptitude')} style={{ minHeight: 48, padding: '0 28px', background: '#0A1628', color: 'white', border: 'none', borderRadius: 12, fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 15, cursor: 'pointer' }}>\n                      Go to Aptitude Zone →\n                    </button>\n                  </div>\n                ) : (\n                  <div>\n                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 12, marginBottom: 20 }}>\n                      {[\n                        { label: '🏆 Best Score', value: bestScore, unit: 'pts' },\n                        { label: '📝 Attempts', value: totalAttempts, unit: 'quizzes' },\n                        { label: '⚡ Sutras Used', value: allSutras.length, unit: 'sutras' },\n                        ...(classGroup ? [{ label: '🎓 Your Group', value: classGroup, unit: '' }] : []),\n                      ].map((s, i) => (\n                        <div key={i} style={{ ...glass, padding: 20, textAlign: 'center' }}>\n                          <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563', marginBottom: 6 }}>{s.label}</div>\n                          <div style={{ fontFamily: 'var(--font-mono)', fontSize: typeof s.value === 'string' ? 14 : 28, fontWeight: 700, color: '#0A1628' }}>{s.value}</div>\n                          {s.unit && <div style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#9CA3AF' }}>{s.unit}</div>}\n                        </div>\n                      ))}\n                    </div>\n                    {allSutras.length > 0 && (\n                      <div style={{ ...glass, padding: 20, marginBottom: 20 }}>\n                        <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, fontWeight: 700, color: '#0A1628', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Vedic Sutras Mastered</div>\n                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>\n                          {allSutras.map(s => (\n                            <span key={s} style={{ background: '#DBEAFE', color: '#1E40AF', borderRadius: 100, padding: '5px 14px', fontFamily: 'var(--font-body)', fontSize: 13, fontWeight: 600 }}>{s}</span>\n                          ))}\n                        </div>\n                      </div>\n                    )}\n                    <div style={{ ...glass, padding: 20 }}>\n                      <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, fontWeight: 700, color: '#0A1628', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '0.06em' }}>Recent History</div>\n                      {history.slice(-5).reverse().map((h, i) => (\n                        <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: i < Math.min(4, history.length - 1) ? '1px solid rgba(30,64,175,0.07)' : 'none' }}>\n                          <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563' }}>{new Date(h.date).toLocaleDateString()}</div>\n                          <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 15, color: '#0A1628' }}>{h.score} pts</div>\n                        </div>\n                      ))}\n                    </div>\n                  </div>\n                )}\n              </div>\n            );\n          })()}\n\n          {/* ── VEDIC LEADERBOARD ── */}\n          {activeTab === 'vedic' && <>\n          {/* ── SCOPE TABS ── */}\n          <div className=\"lb-scope-scroll\" style={{ marginBottom: 12 }}>\n            <div style={{ display: 'inline-flex', gap: 4, background: 'white', borderRadius: 14, padding: 4, border: '1px solid rgba(30,64,175,0.12)', whiteSpace: 'nowrap' }}>\n              {SCOPES.map(s => (\n                <button\n                  key={s.id}\n                  onClick={() => { setActiveScope(s.id); setVisibleCount(20); }}\n                  style={{\n                    padding: '8px 20px', minHeight: 40, borderRadius: 10, border: 'none', cursor: 'pointer',\n                    fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 14,\n                    background: activeScope === s.id ? '#0A1628' : 'transparent',\n                    color: activeScope === s.id ? 'white' : '#4B5563',\n                    transition: 'all 0.15s',\n                  }}\n                >\n                  {s.label}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* ── PERIOD PILLS ── */}\n          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 24 }}>\n            {PERIODS.map(p => (\n              <button\n                key={p.id}\n                onClick={() => setActivePeriod(p.id)}\n                style={{\n                  padding: '6px 16px', minHeight: 36, borderRadius: 100, cursor: 'pointer',\n                  fontFamily: 'var(--font-body)', fontSize: 13, border: '1px solid',\n                  background: activePeriod === p.id ? '#DBEAFE' : 'white',\n                  color: activePeriod === p.id ? '#1E40AF' : '#4B5563',\n                  borderColor: activePeriod === p.id ? '#1E40AF' : 'rgba(30,64,175,0.12)',\n                }}\n              >\n                {p.label}\n              </button>\n            ))}\n          </div>\n\n          {/* ── TOP 3 PODIUM ── */}\n          <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'center', gap: 8, marginBottom: 32 }}>\n            {podiumOrder.map(idx => {\n              const entry = top3[idx];\n              if (!entry) return null;\n              return (\n                <div key={entry.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', flex: 1, maxWidth: 200 }}>\n                  {/* Card */}\n                  <div className=\"lb-podium-card\" style={{\n                    background: 'white', borderRadius: '16px 16px 0 0', padding: 16,\n                    textAlign: 'center', boxShadow: '0 -4px 20px rgba(10,22,40,0.08)', width: '100%',\n                  }}>\n                    <div style={{ fontSize: 32, marginBottom: 8 }}>{medals[idx]}</div>\n                    <div\n                      className=\"lb-podium-avatar\"\n                      style={{\n                        width: 52, height: 52, borderRadius: '50%',\n                        background: avatarColors[idx],\n                        display: 'flex', alignItems: 'center', justifyContent: 'center',\n                        margin: '0 auto', fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 16, color: '#0A1628',\n                        border: entry.isCurrentUser ? '3px solid #3B82F6' : 'none',\n                      }}\n                    >\n                      {entry.name.charAt(0)}\n                    </div>\n                    <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 13, color: '#0A1628', marginTop: 8, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: '100%' }}>\n                      {entry.isAnonymous ? 'Anonymous 🎭' : entry.name}\n                    </div>\n                    <div style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: '#4B5563' }}>{entry.grade}</div>\n                    <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 18, color: scoreColors[idx], marginTop: 4 }}>{entry.score}</div>\n                  </div>\n                  {/* Base */}\n                  <div style={{\n                    background: avatarColors[idx], width: '100%',\n                    height: baseHeights[idx],\n                    display: 'flex', alignItems: 'center', justifyContent: 'center',\n                  }}>\n                    <span style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 24, color: scoreColors[idx] }}>\n                      {idx + 1}\n                    </span>\n                  </div>\n                </div>\n              );\n            })}\n          </div>\n\n          {/* ── TABLE HEADER ── */}\n          <div className=\"lb-table-cols\" style={{ display: 'grid', padding: '8px 16px', gap: 8, marginBottom: 6 }}>\n            {['RANK', 'STUDENT', <span key=\"g\" className=\"lb-hide-mobile\">GRADE</span>, 'SCORE', <span key=\"str\" className=\"lb-hide-mobile\">STREAK</span>, 'CHANGE'].map((h, i) => (\n              <div key={i} style={{ fontFamily: 'var(--font-body)', fontSize: 11, color: '#9CA3AF', textTransform: 'uppercase', letterSpacing: '0.06em' }}>{h}</div>\n            ))}\n          </div>\n\n          {/* ── TABLE ROWS (rank 4+) ── */}\n          {tableRows.map(entry => {\n            const isUser = entry.isCurrentUser;\n            return (\n              <div\n                key={entry.id}\n                className=\"lb-table-cols\"\n                style={{\n                  display: 'grid', gap: 8, alignItems: 'center',\n                  background: isUser ? 'rgba(59,130,246,0.06)' : 'white',\n                  border: isUser ? '1.5px solid rgba(59,130,246,0.25)' : '1px solid transparent',\n                  borderRadius: 12, marginBottom: 6, padding: '10px 16px',\n                }}\n              >\n                {/* Rank */}\n                <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 15, color: entry.rank <= 10 ? '#0A1628' : '#9CA3AF' }}>\n                  {entry.rank}\n                </div>\n                {/* Student */}\n                <div style={{ display: 'flex', alignItems: 'center', gap: 8, overflow: 'hidden' }}>\n                  <div style={{\n                    width: 32, height: 32, borderRadius: '50%', flexShrink: 0,\n                    background: isUser ? '#0A1628' : '#F0F4FF',\n                    display: 'flex', alignItems: 'center', justifyContent: 'center',\n                    fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 12,\n                    color: isUser ? 'white' : '#0A1628',\n                  }}>\n                    {entry.name.charAt(0)}\n                  </div>\n                  <div style={{ overflow: 'hidden' }}>\n                    <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 14, color: '#0A1628', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>\n                      {entry.isAnonymous ? 'Anonymous 🎭' : entry.name.slice(0, 20) + (entry.name.length > 20 ? '…' : '')}\n                      {isUser && <span style={{ color: '#3B82F6' }}> (You)</span>}\n                    </div>\n                  </div>\n                </div>\n                {/* Grade */}\n                <div className=\"lb-hide-mobile\" style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#4B5563' }}>{entry.grade}</div>\n                {/* Score */}\n                <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 16, color: '#0A1628' }}>{entry.score}</div>\n                {/* Streak */}\n                <div className=\"lb-hide-mobile\" style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#F59E0B' }}>🔥{entry.streak}</div>\n                {/* Change */}\n                <div style={{\n                  fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 13,\n                  color: entry.movement === 'up' ? '#10B981' : entry.movement === 'down' ? '#EF4444' : '#9CA3AF',\n                }}>\n                  {entry.movement === 'up' ? `↑${entry.movementAmount}` : entry.movement === 'down' ? `↓${entry.movementAmount}` : '─'}\n                </div>\n              </div>\n            );\n          })}\n\n          {/* Show more */}\n          {remaining > 0 && (\n            <button\n              onClick={() => setVisibleCount(c => c + 20)}\n              style={{\n                width: '100%', minHeight: 44, background: 'white',\n                border: '1px solid rgba(30,64,175,0.15)', borderRadius: 10,\n                padding: 10, fontFamily: 'var(--font-body)', fontSize: 14,\n                color: '#4B5563', textAlign: 'center', cursor: 'pointer', marginBottom: 8,\n              }}\n            >\n              Show more ({remaining} more students)\n            </button>\n          )}\n\n          {/* Pinned user row if not visible */}\n          {!userVisible && userEntry && (\n            <>\n              <div style={{ textAlign: 'center', fontFamily: 'var(--font-body)', fontSize: 12, color: '#9CA3AF', margin: '8px 0' }}>─── Your position ───</div>\n              {userEntry.isOptedOut ? (\n                <div style={{ background: 'rgba(30,64,175,0.04)', border: '1px solid rgba(30,64,175,0.12)', borderRadius: 12, padding: '12px 16px' }}>\n                  <span style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563', fontStyle: 'italic' }}>\n                    You are hidden from the leaderboard\n                  </span>\n                </div>\n              ) : (\n                <div\n                  className=\"lb-table-cols\"\n                  style={{\n                    display: 'grid', gap: 8, alignItems: 'center',\n                    background: 'rgba(59,130,246,0.08)', border: '1.5px solid #3B82F6',\n                    borderRadius: 12, padding: '10px 16px',\n                  }}\n                >\n                  <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 15, color: '#3B82F6' }}>{userEntry.rank}</div>\n                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>\n                    <div style={{ width: 32, height: 32, borderRadius: '50%', background: '#0A1628', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--font-body)', fontWeight: 700, fontSize: 12, color: 'white' }}>\n                      {userEntry.name.charAt(0)}\n                    </div>\n                    <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 14, color: '#0A1628' }}>\n                      {userEntry.name}<span style={{ color: '#3B82F6' }}> (You)</span>\n                    </div>\n                  </div>\n                  <div className=\"lb-hide-mobile\" style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#4B5563' }}>{userEntry.grade}</div>\n                  <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 16, color: '#0A1628' }}>{userEntry.score}</div>\n                  <div className=\"lb-hide-mobile\" style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#F59E0B' }}>🔥{userEntry.streak}</div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontWeight: 600, fontSize: 13, color: '#10B981' }}>↑{userEntry.movementAmount}</div>\n                </div>\n              )}\n            </>\n          )}\n\n          {/* ── USER STATS FOOTER ── */}\n          <div style={{ ...glass, padding: 20, marginTop: 16 }}>\n            <div className=\"lb-stats-grid\" style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16, marginBottom: 16 }}>\n              {/* Percentile */}\n              <div style={{ textAlign: 'center' }}>\n                <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563', marginBottom: 6 }}>📊 Your Percentile</div>\n                <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 28, color: percentile >= 75 ? '#10B981' : percentile >= 50 ? '#F59E0B' : '#4B5563' }}>\n                  {percentile}%\n                </div>\n                <div style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#9CA3AF' }}>of {activeScope} students</div>\n              </div>\n              {/* Score */}\n              <div style={{ textAlign: 'center' }}>\n                <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563', marginBottom: 6 }}>⭐ Performance Score</div>\n                <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 28, color: '#0A1628' }}>{userEntry?.score ?? 0} pts</div>\n              </div>\n              {/* Rank */}\n              <div style={{ textAlign: 'center' }}>\n                <div style={{ fontFamily: 'var(--font-body)', fontSize: 13, color: '#4B5563', marginBottom: 6 }}>🏆 Your Rank</div>\n                <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, fontSize: 28, color: '#0A1628' }}>#{userEntry?.rank ?? '—'}</div>\n              </div>\n            </div>\n\n            <div style={{ borderTop: '1px solid rgba(30,64,175,0.1)', paddingTop: 16 }}>\n              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 16 }}>\n                <div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontSize: 14, color: '#0A1628', fontWeight: 500 }}>Show me on leaderboard</div>\n                  <div style={{ fontFamily: 'var(--font-body)', fontSize: 12, color: '#4B5563', marginTop: 2 }}>Off = you appear as Anonymous 🎭</div>\n                </div>\n                <Toggle value={!progress.leaderboardOptOut} onChange={handleOptOut} />\n              </div>\n            </div>\n          </div>\n\n          </>}\n\n        </motion.div>\n      </main>\n    </div>\n  );\n}"};

let written = 0;
for (const [relPath, content] of Object.entries(FILES)) {
  const fullPath = path.join(ROOT, relPath);
  fs.writeFileSync(fullPath, content, 'utf8');
  console.log('  ✅', relPath);
  written++;
}
console.log('\n✅ Done! ' + written + ' files fixed.');
console.log('Now run: npm run dev\n');
